(async () => {
  const { Field } = await import('/src/world/field.js');
  const R2D = 180 / Math.PI;
  window.__CS = {
    on: false, s: [], label: '',
    start(l) { this.label = l || ''; this.s = []; this.on = true; return 'sampling ' + this.label; },
    stop() { this.on = false; return this.report(); },
    report() {
      const s = this.s;
      if (s.length < 8) return { label: this.label, n: s.length, err: 'too few samples' };
      const dp = [], da = [], dtv = [];
      for (let i = 1; i < s.length; i++) {
        const a = s[i-1], b = s[i];
        dp.push(Math.hypot(b.px-a.px, b.py-a.py, b.pz-a.pz));
        let dot = Math.abs(a.qx*b.qx + a.qy*b.qy + a.qz*b.qz + a.qw*b.qw);
        dot = Math.min(1, dot);
        da.push(2 * Math.acos(dot) * R2D);
        dtv.push(b.t - a.t);
      }
      const med = (arr) => { const c = arr.slice().sort((x,y)=>x-y); return c[Math.floor(c.length/2)]; };
      const mx = (arr) => arr.reduce((m,v)=>Math.max(m,v), 0);
      const jerkP = [], jerkA = [];
      for (let i = 1; i < dp.length; i++) { jerkP.push(Math.abs(dp[i]-dp[i-1])); jerkA.push(Math.abs(da[i]-da[i-1])); }
      const heros = s.map(v=>v.hero).filter(v=>typeof v === 'number');
      const fxs = s.map(v=>Math.abs(v.fx)).filter(v=>typeof v === 'number');
      const clr = s.map(v=>v.clr).filter(v=>typeof v === 'number');
      const zoom = s.map(v=>Math.abs(v.dist - v.distT));
      const r3 = (v) => +Number(v).toFixed(3);
      return {
        label: this.label, n: s.length, secs: r3((s[s.length-1].t - s[0].t)/1000),
        medFrameMs: r3(med(dtv)), maxFrameMs: r3(mx(dtv)),
        stepMed: r3(med(dp)), stepMax: r3(mx(dp)), stepRatio: r3(mx(dp)/Math.max(1e-6, med(dp))),
        turnMedDeg: r3(med(da)), turnMaxDeg: r3(mx(da)), turnRatio: r3(mx(da)/Math.max(1e-6, med(da))),
        jerkPosMax: r3(mx(jerkP)), jerkAngMax: r3(mx(jerkA)),
        heroMin: r3(Math.min(...heros)), heroMax: r3(Math.max(...heros)), heroSpread: r3(Math.max(...heros)-Math.min(...heros)),
        heroOffCentreMax: r3(Math.max(...fxs)),
        zoomMax: r3(mx(zoom)),
        lensClearanceMin: clr.length ? r3(Math.min(...clr)) : null,
        occludedFrames: s.filter(v=>v.occ > 0).length, ghostMax: r3(mx(s.map(v=>v.ghost||0))),
        fadeMsMax: r3(mx(s.map(v=>v.fms||0))),
      };
    },
  };
  const tick = () => {
    requestAnimationFrame(tick);
    if (!window.__CS.on) return;
    try {
      const w = Field.world(); if (!w) return;
      const cam = w.camera, m = w.map;
      const st = __DQ.state().field.camera;
      const f = __DQ.cameraFrame();
      const oc = __DQ.cameraOccluders ? __DQ.cameraOccluders() : null;
      let clr = null;
      if (m && typeof m.heightAt === 'function') clr = cam.position.y - m.heightAt(cam.position.x, cam.position.z);
      window.__CS.s.push({ t: performance.now(),
        px: cam.position.x, py: cam.position.y, pz: cam.position.z,
        qx: cam.quaternion.x, qy: cam.quaternion.y, qz: cam.quaternion.z, qw: cam.quaternion.w,
        dist: st.dist, distT: st.distTarget, hero: f && f.heroPct, fx: f && f.heroNdcX, feet: f && f.feetPct,
        clr, occ: (st.fade && st.fade.occluding) || 0,
        ghost: oc && oc.length ? Math.max.apply(null, oc.map(o => o.alpha != null ? o.alpha : 0)) : 0,
        fms: (st.fade && st.fade.ms) || 0 });
    } catch (e) {}
  };
  requestAnimationFrame(tick);
  return 'sampler installed';
})()
